initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT containing an initial Subscription ${subscription} 
        with an id set to ${subscription_id}
        and an initial Entity ${entity}
        with an id set to ${entity_id}
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Merge Entity with Response Status Code set to 204     and
        Notification with Notification containing entity element set to 'entity-different-attributes-types-deleted-street-attribute-normalized.json'
}

then {
    the SUT sends a valid Response for the operations:
        Update Entity Attributes with Response Status Code set to 204     and
        Notification with Notification containing entity element set to 'entity-different-attributes-types-deleted-street-attribute-normalized.json'
}

then {
    the SUT sends a valid Response for the operations:
        Partial Update Entity Attributes with Response Status Code set to 204     and
        Notification with Notification containing entity element set to 'entity-different-attributes-types-deleted-street-attribute-normalized.json'
}
